set role service_role;
select th.assert((select outcome from public.th_c27_outcome where who = 'holder') = 'saved' and (select outcome from public.th_c27_outcome where who = 'contender') = 'removed', 'both committed');
select th.assert((select coalesce(array_agg(a_plaid_transaction_id order by a_plaid_transaction_id), '{}') from public.card_payment_decisions where kind = 'pair_counterpart_removed' and superseded_by is null) = array['c27-p'] and not exists (select 1 from public.card_payment_decisions where kind = 'destination_removed_card'), 'the removal saw the confirmation that committed just before it and preserved it as the user''s own decision (not as a system record)');
select th.assert(not exists (select 1 from public.card_payment_decisions where kind = 'pair'), 'the pair itself went with the card''s account');
select th.assert((public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->>'fresh')::boolean and (select evaluated_version = input_version from public.card_payment_eval_versions where user_id = '00000000-0000-0000-0000-0000000000aa'), 'fresh after the removal, the last writer');
select th.assert((select (l->>'state') || '/' || (l->>'reason') || '/' || coalesce(l->>'effectCents', 'null') from (select l from jsonb_array_elements(public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->'legs') l where (l->>'transactionId')::uuid = (select id from public.transactions where plaid_transaction_id = 'c27-p')) x(l)) = 'untracked/removed_card/-10000', 'the confirmed payment counts as leaving the tracked accounts — not unresolved');
